-- ============================================================================
-- Сроки охоты в Московской области — добавление региона.
-- Выполняйте в Supabase → SQL Editor.
-- Скрипт идемпотентен: сначала удаляет прежние записи ТОЛЬКО этого региона,
-- затем вставляет заново. Другие регионы не затрагиваются.
-- Плавающие даты — правилами date_rule / close_rule:
--   'N-wd:MM' — N-й день недели месяца (1-sat:04 = 1-я суббота апреля);
--   '+N'      — продолжительность: закрытие = открытие + N дней (10 дней охоты).
-- В open_date / close_date — даты-подсказки (на сезон 2026/27).
-- ============================================================================

alter table public.hunting_seasons add column if not exists date_rule text;
alter table public.hunting_seasons add column if not exists close_rule text;

delete from public.hunting_seasons where region_id = 'moscow';

insert into public.hunting_seasons
